data.transform:
(
	$id := $cuid();
	$newSeq := $state.context.REQUEST.data.sequence + 1;
	$workOrderId := $state.context.REQUEST.data.workOrderId;
	$slidingProcesses := [
		$
			.workOrder
			.edges
			.node
			.workOrderProcesses
			.edges
			.node[sequence >= $newSeq]
	];
	/* only need to update sequence number, this path of route has no dependencies or dists */
	{
		"payloadCreate": [
			{
				"create": {
					"id": $id,
					"sequence": $newSeq,
					"active": true,
					"unitWeight": 0,
					"processId": "Default",
					"workOrderId": $workOrderId
				}
			}
		],
		"payloadUpdate": [
			$slidingProcesses#$i
				.{
					"update": { "sequence": sequence + ($i + 1) },
					"where": { "id": id }
				}
		]
	}
)

