data.query:
query (
  $where: WorkOrderWhereInput
  $orderBy: [WorkOrderOrderByInput!]
  $first: Int
  $after: String
  $whereDep: WorkOrderProcessDistributionDependencyWhereInput
  $orderByDep: [WorkOrderProcessDistributionDependencyOrderByInput!]
) {
  workOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        priority
        quantity
        active
        buildToOrder
        buildToStock
        kanban
        customerReference
        description
        extProduct
        externalId
        orderReference
        actualFinishAt
        actualStartAt
        scheduledFinishAt
        scheduledStartAt
        dueAt
        earliestStartAt
        productId
        productStrategyId
        workOrderStatusId
        workOrderProcesses(orderBy: [{ field: sequence, direction: asc }]) {
          edges {
            node {
              id
              sequence
              standardPackQuantity
              unitWeight
              active
              description
              extWorkOrderProcess
              externalId
              name
              note
              documentDesignId
              imageId
              processId
              workOrderProcessDistributions {
                edges {
                  node {
                    id
                    dispatchSequence
                    unitPerCycle
                    balanceQuantity
                    producedQuantity
                    productionOperators
                    quantity
                    setupOperators
                    active
                    extWorkunit
                    group
                    name
                    actualFinishAt
                    actualStartAt
                    scheduledFinishAt
                    scheduledStartAt
                    cycleDuration
                    idealDuration
                    processDuration
                    scheduledDuration
                    setupDuration
                    standardDuration
                    transitAfter
                    transitBefore
                    distributionStatusId
                    leadingDistributionId
                    workOrderProcessId
                    workunitId
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  workOrderProcessDistributionDependency(
    where: $whereDep
    orderBy: $orderByDep
  ) {
    edges {
      node {
        id
        childWorkOrderProcessDistributionId
        childWorkOrderProcessDistribution {
          workOrderProcess {
            workOrderId
          }
        }
        parentWorkOrderProcessDistributionId
        parentWorkOrderProcessDistribution {
          workOrderProcess {
            workOrderId
          }
        }
      }
    }
  }
}

